#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(3));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> qs[i][j];
        }
    }

    vector<long long> vals(a.begin(), a.end());
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();
    vector<int> lc(1, 0), rc(1, 0), ct(1, 0), roots(1, 0);
    for (long long i = 0; i < n; i++) {
        int v = (int)(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin());
        int prev = roots.back();
        int cur = (int)ct.size();
        roots.push_back(cur);
        lc.push_back(0);
        rc.push_back(0);
        ct.push_back(ct[prev] + 1);
        int lo = 0, hi = m - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int nn = (int)ct.size();
            lc.push_back(0);
            rc.push_back(0);
            if (v <= mid) {
                rc[cur] = rc[prev];
                lc[cur] = nn;
                ct.push_back(ct[lc[prev]] + 1);
                prev = lc[prev];
                hi = mid;
            } else {
                lc[cur] = lc[prev];
                rc[cur] = nn;
                ct.push_back(ct[rc[prev]] + 1);
                prev = rc[prev];
                lo = mid + 1;
            }
            cur = nn;
        }
    }
    string out;
    for (long long j = 0; j < q; j++) {
        int u = roots[qs[j][0] - 1], w = roots[qs[j][1]];
        long long k = qs[j][2];
        int lo = 0, hi = m - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            long long c = ct[lc[w]] - ct[lc[u]];
            if (k <= c) {
                u = lc[u];
                w = lc[w];
                hi = mid;
            } else {
                k -= c;
                u = rc[u];
                w = rc[w];
                lo = mid + 1;
            }
        }
        if (!out.empty()) out += " ";
        out += to_string(vals[lo]);
    }
    cout << out << "\n";

    return 0;
}

