import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][3];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cnt = (int) n;
        long[] keys = new long[cnt];
        for (int i = 0; i < cnt; i++) keys[i] = (a[i] << 16) | i;
        Arrays.sort(keys);
        int[] rk = new int[cnt];
        long[] vals = new long[cnt];
        int m = 0;
        long lastv = -1;
        for (int i = 0; i < cnt; i++) {
            long v = keys[i] >> 16;
            if (v != lastv) {
                vals[m++] = v;
                lastv = v;
            }
            rk[(int) (keys[i] & 65535)] = m - 1;
        }
        int cap = cnt * 18 + 5;
        int[] lc = new int[cap], rc = new int[cap], ct = new int[cap];
        int[] roots = new int[cnt + 1];
        int used = 1;
        for (int i = 0; i < cnt; i++) {
            int v = rk[i];
            int prev = roots[i];
            int cur = used++;
            roots[i + 1] = cur;
            ct[cur] = ct[prev] + 1;
            int lo = 0, hi = m - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                int nn = used++;
                if (v <= mid) {
                    rc[cur] = rc[prev];
                    lc[cur] = nn;
                    ct[nn] = ct[lc[prev]] + 1;
                    prev = lc[prev];
                    hi = mid;
                } else {
                    lc[cur] = lc[prev];
                    rc[cur] = nn;
                    ct[nn] = ct[rc[prev]] + 1;
                    prev = rc[prev];
                    lo = mid + 1;
                }
                cur = nn;
            }
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < q; j++) {
            int u = roots[(int) qs[j][0] - 1], w = roots[(int) qs[j][1]];
            long k = qs[j][2];
            int lo = 0, hi = m - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                long c = ct[lc[w]] - ct[lc[u]];
                if (k <= c) {
                    u = lc[u];
                    w = lc[w];
                    hi = mid;
                } else {
                    k -= c;
                    u = rc[u];
                    w = rc[w];
                    lo = mid + 1;
                }
            }
            if (j > 0) out.append(" ");
            out.append(vals[lo]);
        }
        System.out.println(out);
    }
}
